from pathlib import Path
p=Path('prompt-engine.js')
t=p.read_text()
start=t.index('const stageSpecial=Object.freeze({')
end=t.index('\nconst procedures=',start)
stages={
1:"Perform complete human-authority intake only. Exhaust the human-authority intake before Stage 01 can complete. Capture every materially relevant human-supplied fact, requirement, constraint, decision, prohibition, requested output, acceptance condition, material reference, dependency, exception, definition, and unresolved human-only issue from current user input and every actually accessible supplied material. The user supplies project information once: never ask the human to repeat, retype, restate, summarize, reconstruct, reattach, or resend information already supplied or available in authorized material. Derive subject-specific human-only questions from the actual request and supplied material, never from hard-coded project-subject branches. Classify every missing issue as BLOCKING_NOW, ASK_NOW_NONBLOCKING, or LATER_RESOLVABLE. Ask every BLOCKING_NOW and ASK_NOW_NONBLOCKING human-only question conversationally before final JSON; unknown/deferred is allowed for ASK_NOW_NONBLOCKING. Do not ask LATER_RESOLVABLE questions. Inspect accessible supplied artifacts deeply enough to extract human-authority statements needed to define the job, but do not perform external research, authority analysis, requirement atomization, test design, production design, artifact generation, filing, simulation, manufacturing, or product verification. When named material bytes are unavailable, preserve its identity, do not infer substantive content from the filename, and block only when objective or deliverable identification actually depends on those bytes. Classify every APPLICATION INTAKE MANIFEST unit exactly once and preserve the complete structured capture in INPUT_SET_CONTENTS. Do not complete until objective and intended deliverable are defined, required supplied materials are identified, every controlled input unit is accounted for, every foreseeable human-only issue is supplied/answered/deferred, and no later-stage work was performed. The accepted Stage 01 capture is durable project memory for every later stage.",
2:"Build only the complete independent external source inventory needed for the current job. Use the accepted Stage 01 job definition, current human input, known source leads, constraints, requested outcome, and authorized research capability to discover every potentially controlling or materially relevant independent external source. Supplied project artifacts remain project input and are not automatically independent authority. Inspect each proposed external source sufficiently to establish identity, issuer/author, source type, origin, URL/reference, version/date, authority level and role, relevance, applicable portions, inspection status, currency, supersession, and controlling status. Establish an explicit authority hierarchy and identify source conflicts; resolve controlling conflicts where objectively possible and preserve unresolved controlling conflicts as blockers. Treat desired source count only as search guidance, never as a quota that authorizes invention. Stage 02 completes only when the relevant source landscape has been exhausted sufficiently to support either at least one legitimate inspected external source/authority or an evidence-supported NO_APPLICABLE_EXTERNAL_SOURCE determination. Do not perform Stage 03 substantive research or derive requirements here.",
3:"Exhaust the complete current accepted Stage 02 source set and preserve the complete requirement-relevant human authority already captured by Stage 01. Research every current source source-by-source, applicable-portion-by-applicable-portion, and pass-by-pass. Separately extract mandatory statements, recommendations, optional practices, examples, explanatory material, prohibitions, exceptions, dependencies, applicability facts, restrictions, invalidating material, conflicts, superseded guidance, source evidence, candidate obligations, and unresolved research gaps. Every current Stage 02 source must have current research coverage unless Stage 02 validly established NO_APPLICABLE_EXTERNAL_SOURCE. Carry forward every requirement-relevant Stage 01 human-origin obligation with its existing identity and provenance; never weaken it, summarize it away, pretend it came from an external source, or ask the human to resupply it. Perform the required conflict/exception pass and repeat complete passes until the latest complete pass introduces no new material category. Do not finalize while any current source lacks coverage, any requirement-relevant Stage 01 obligation lacks carry-forward coverage, any conflict/exception pass is incomplete, or saturation is unsupported. Do not atomize the final requirement specification yet.",
4:"Compile the complete atomic requirement specification only from the application-generated APPLICATION OBLIGATION MANIFEST and the exhaustive Stage 01 plus Stage 03 context supplied in this prompt. Treat that manifest as the closed input universe assembled from current User Job Input, accepted Stage 01 semantic capture and job definition, obligations extracted from accessible supplied project material, accepted Stage 03 research, candidate external-source obligations, and applicable source identities/evidence. Use every material detail. Never ask the human to repeat, restate, summarize, retype, reconstruct, attach, reattach, or resend information already supplied or captured. Account for every obligationId exactly once: map it to one or more atomic requirements, retain it as nonnormative context, mark it explicitly inapplicable with reason, or block it with reason. No obligation may disappear. Preserve every original obligation identity independently even when materially equivalent obligations consolidate. Every resulting requirement must be atomic enough to test independently where possible and preserve provenance, source identity/location where applicable, applicability, dependencies, prohibitions, defined terms, observable satisfaction condition, intended verification semantics, expected evidence, failure condition, and severity. Schema-valid output is invalid if accounting closure is incomplete.",
5:"Resolve the complete current requirement set before verification design. Inspect every current requirement and its Stage 04 provenance/accounting. Detect duplicates, semantic overlaps, conflicts, impossible combinations, undefined terms, circular dependencies, missing prerequisites, unsupported requirements, applicability uncertainty, and requirements without a viable verification path. For every defect preserve affected requirement identities, governing evidence, exact resolution or blocker, changed requirement references, and downstream impact. Never silently delete, merge, weaken, reinterpret away, or guess through a requirement conflict. Genuine user tradeoffs or corrections to human authority use the human-decision path; researchable or application-known facts must not be pushed back to the user. When the requirement set changes, provide the substantive correction and let the application create the new requirements version and invalidate downstream work.",
6:"Design the complete verification suite before production instructions are authored. Use the resolved current requirements, requirement resolutions, governing evidence, current artifact knowledge, available capabilities, and application-published Test IR grammar. Every active mandatory requirement must have at least one complete ready verification path and exact mandatory coverage must be achievable. For every test define the proposition, TEST_TYPE, EXECUTION_MODE, REQUIRED_CAPABILITY, required artifacts/inputs, tools, procedure, expected result, failure condition, and evidence to preserve. For every mandatory requirement explicitly analyze how a defective product could falsely appear compliant, including boundaries, partial-success cases, stale state, malformed input/state, incorrect authority, wrong artifact, and capability substitution; put direct verification checks in Stage 06 and route realistic invalid/mutation mechanisms to Stage 07. When a proposition can be faithfully expressed using only the registered Closed Loop Test IR primitives and bindings, select APPLICATION_DETERMINISTIC and produce valid TEST_IR. Never invent operations, parsers, code, shell, JavaScript, Python, network behavior, or runtime semantics. When deterministic reduction would lose substantive meaning, select the exact non-native route: EXTERNAL_AGENT_TOOL, INDEPENDENT_AGENT_REVIEW, HUMAN_INSPECTION, EXTERNAL_SYSTEM, or UNAVAILABLE. Determine executor, capability, required artifacts, and required evidence now. A fully defined mandatory unavailable capability remains blocked. A test definition is not execution and a filename/code block is not artifact possession.",
7:"Build and actually execute the complete applicable failure-test suite. Use the current requirements, verification design, supported Test IR/capabilities, and artifact custody to identify realistic invalid states that could expose false positives or validator weakness. For every applicable mutation define the violation mode, actual fixture identity/bytes where byte-backed, expected rejection, required capable execution route, actual observed result, and sufficient evidence. Include relevant missing inputs, invalid values, wrong versions, duplicate identifiers, contradictions, omitted required material, prohibited content, corrupt references, malformed files/state, stale state, incorrect authority, wrong artifact, unavailable capability substitution, injected instructions, and known-invalid artifacts. Fixture creation is not fixture execution; proposed fixtures alone cannot complete the stage. If a required capability or byte-backed fixture is unavailable, fail closed rather than invent execution. Any invalid fixture that is accepted must create or link the corresponding validator defect.",
8:"Author one complete production instruction from the resolved current requirement set and verification architecture. The instruction itself must be sufficient for a production agent to create the requested deliverable without guessing. Include objective, authorized inputs, input-failure rules, source authority, scope, prohibitions, defined terms, complete ordered procedure, all decision/branch rules, tool rules, exact output contract, TRUE/FALSE/UNKNOWN handling, verification and failure handling, and completion criteria. Trace every current mandatory requirement to the exact instruction clause or behavior that implements it; no mandatory requirement may be absent. Use the current verification suite and failure modes to prevent instructions that could yield superficially valid but incorrect output. For multi-file or tool-generated work define exact artifacts/components, filenames/logical paths, interfaces, dependencies, transformations, toolchain requirements, and required downstream verification. Distinguish creating artifact bytes from later executing/importing/simulating/fabricating/filing them; require the actual artifact whenever its exact bytes can be reliably constructed.",
9:"Preflight the complete current production instruction in an independent reviewer context. Review every material clause, not a sample. Check for multiple interpretations, undefined objects/terms, unsupplied dependencies, internal conflicts, unavailable required capabilities, unverifiable instructions, ambiguous ordering, missing failure behavior, missing responsibility assignment, incomplete requirement traceability, and contradictions with the resolved requirements or verification architecture. Preserve findings and evidence clause-by-clause. Do not execute production. If any material finding requires correction, identify the exact instruction correction; the application creates the new instruction version, invalidates downstream work, and Stage 09 must repeat against the corrected instruction. No material finding may remain unresolved at completion.",
10:"Freeze the exact test candidate selected by the human. Use the current approved production instruction, successful preflight, required controlled components/artifacts, current versions, tool configuration, settings, permissions, and limitations. The human selects authorized candidate components; the application assigns candidate and iteration identities, verifies and freezes exact available bytes, computes authoritative hashes, and prevents in-place mutation. Review whether every required component is present, correctly identified, byte-backed where required, consistently configured, and capable of being supplied identically to all ten runs. Do not invent IDs, hashes, freeze state, or application-derived equality. Do not begin Stage 11 execution here.",
11:"Execute the frozen candidate exactly ten times in application-reserved independent contexts. For the current reserved run lane, use only the exact frozen candidate package, supplied RUN_ID/CONTEXT_ID, authorized project inputs, and allowed tool configuration. Do not see or use another run output, reviewer feedback, failure explanation, RCA, proposed correction, or later-stage evidence. Preserve complete output, actual tool configuration, actual execution failures, produced artifacts, and contamination observations for this run. Never invent run/context identities or claim independence merely because instructed to be independent. The application determines candidate equality, component-hash equality, package equality, context distinctness, contamination consequences, run count, and the exactly-ten gate. Every run remains separately preserved.",
12:"Verify every required current REQ_ID × RUN_ID × TEST_ID cell independently using only the application-selected target run or blind alias, requirement, test, required artifacts, and governing evidence. Respect the stored EXECUTION_MODE and execution route exactly; never substitute an AI reviewer for human inspection, an external system, external tool, or application-native execution. Do not fabricate application-native execution. The verifier context must differ from the generator context and must not receive generator self-evaluation, other verifier determinations, Stage 13 comparison, RCA, or proposed corrections. Execute each listed missing triple only when the required capability and exact artifact bytes are actually available. Preserve observed result, expected result, exact procedure, verifier/context evidence, and evidence capable of establishing the proposition. Prose cannot prove byte identity; hashes alone cannot prove meaning; agent assertion cannot prove human inspection. Return SATISFIED, VIOLATED, or UNDETERMINED only as supported. The stage is complete only when the application has exactly one current valid independent sufficiently evidenced determination for every required triple.",
13:"Compare the complete ten-run verification set requirement-by-requirement. Use all ten current runs for every mandatory requirement. Preserve every materially relevant agreement, disagreement, violation, undetermined result, interpretation variance, prohibited output variance, inconclusive test, repeated failure group, unique failure, correctness-affecting variance, and linked defect/evidence. Never omit, discard, average away, or prefer an inconvenient run. Every correctness-affecting variance that requires a defect must receive one. The application calculates all-ten satisfaction, any-violation, any-undetermined, exact counts, agreement rates, stability diagnostics, repeated/unique defect counts, novel-defect discovery by run, and completeness.",
14:"Root-cause every current material defect completely. Trace backward from each observed failure through product/output, execution, instruction, requirement, Stage 03 research, source, human input, tool/configuration, and application audit evidence as applicable. Identify the earliest defective layer supported by evidence, not merely the final symptom. Preserve defect manifestation, affected requirement/run/product, severity, evidence, causal chain, earliest responsible layer, root cause, and required downstream rework. Unknown or unsupported RCA remains blocked. Do not propose a symptom-only patch when an earlier layer is responsible.",
15:"Convert every confirmed defect into a permanent regression and prove the original failure before correction. For each defect preserve the exact failure fixture, fixture identity/hash where byte-backed, reproduction procedure, detection method, correction expectation, applicability, permanent test location, and a separate actual PRE_CORRECTION regression execution with sufficient evidence showing the failure. A statement that the regression would have caught the defect is insufficient. PRE_CORRECTION SATISFIED cannot prove reproduction. The same execution cannot prove later correction. Do not claim post-correction success here; correction success must come from a distinct later current-scope regression execution after the responsible layer has been corrected.",
16:"Correct the root cause identified at Stage 14, not merely the symptom. For every confirmed RCA propose the smallest complete correction to the earliest responsible layer, preserving triggering defect/RCA identities, exact old and proposed new controlled content, affected artifacts/instruction/requirements/tests/configuration, required reruns, and preflight consequences. Execution-only failure must not cause an unsupported instruction change. Do not ask the user to determine the responsible layer; Stage 14 already did that. Genuine human-authority corrections or tradeoffs use the human-decision path. Application-owned IDs, versions, hashes, downstream invalidation, rerun selection, and preservation of old versions remain application-controlled. Never modify a controlled version in place.",
17:"Run the complete corrected iteration through only the declared Stage 17 operation. Use the application-assigned new iteration/candidate, current correction, current requirements/tests/regressions, exact artifacts, and operation-selected identities/context. The complete Stage 17 lifecycle is: freeze the corrected candidate, execute exactly ten new independent runs, independently verify the complete applicable matrix, compare all ten, root-cause every new material defect, create and actually execute required regressions, and correct each responsible root cause. Do not reuse old execution conversations or prior-run outputs. Each operation must perform only its own part of this lifecycle using the complete current inputs supplied for that operation. Application-derived counts and completion flags cannot be asserted by the agent.",
18:"Evaluate convergence from the latest completed current iteration using the complete current requirements, verification results, regression executions, defects, blockers, contradictions, ambiguities, and stability/variance diagnostics. Explain every remaining failed condition and identify the earliest return stage required for correction. The application calculates mandatory requirement coverage, mandatory verification coverage, applicable regression success, critical/major defect counts, unresolved mandatory unknowns, correctness-affecting contradictions/ambiguities, unexplained correctness-affecting variance, and whether all conditions are simultaneously true. Do not set CONVERGED or override calculated values. Completion requires all convergence conditions to be true at the same time.",
19:"Run the unchanged confirmation lifecycle against the exact converged candidate with zero material changes. Confirm the semantic freeze/identity supplied by the application, then execute exactly ten new independent contexts using the identical unchanged package, rerun the complete current verification suite, rerun every applicable active regression, compare all ten runs, and confirm that no new requirement, missed failure, critical/major defect, contradiction, or unexplained correctness-affecting variance exists. Use only the declared Stage 19 operation and its selected context. Do not reuse prior-run output. The application derives zero-change status, exact run counts, test/regression completeness, new-defect/new-requirement counts, variance, and final confirmation acceptance.",
20:"Freeze the production baseline only after successful current unchanged confirmation and explicit human baseline authorization. Review the exact approved controlled versions, components, files, and artifact bytes proposed for baseline. The application assigns BASELINE_ID, freezes exact verified bytes, calculates authoritative hashes, separates the baseline package from working files, and records immutable baseline identity. Report substantive discrepancies or blockers only; do not assign IDs, hashes, approval, or lifecycle state. Any changed component invalidates baseline status rather than being silently accepted.",
21:"Generate the complete finished product from the exact approved production baseline in a fresh production context. Use only authorized baseline materials, current approved production instruction, current human authority, and application-selected production identity/context. Produce every actual requested output artifact whose bytes can be reliably constructed here; do not downgrade a producible artifact to prose merely because a downstream consuming tool is unavailable. Treat compilation, import/open validation, simulation, post-processing, machine execution, fabrication, deployment, filing/submission, and physical testing as separate downstream operations that may be claimed only when actually performed with evidence. Preserve complete execution observations and actual returned artifact bytes. The application owns PRODUCT_ID/version, execution identity, artifact inventory, filenames, media types, byte sizes, authoritative hashes, storage references, and lineage. Any later edit requires a new controlled product version and affected verification.",
22:"Run the complete applicable deterministic verification set against the exact current finished product. Application-native supported TEST_IR tests are executed by the application worker and create application-owned results; an external agent must never imitate or fabricate those executions or receipts. For deterministic tests requiring a declared external capability, perform only the exact routed external deterministic work with the exact product/test artifacts actually supplied and return observations, tool/capability metadata, evidence, and required files. Never substitute prose for execution. The application determines the expected current deterministic test set, validates current test/product identity, normalizes all gate-consumed result fields, counts executed/satisfied/violated/undetermined/missing results, and rejects the product on mandatory failure. Every result must bind to the current product, current test-spec identity, exact input artifacts/hashes, actual capable executor, and sufficient proposition-capable evidence.",
23:"Perform complete independent meaning-based verification only for the current meaning-review requirements selected by the application. Use the actual current product, exact governing requirement, applicable source evidence, and meaning rubric/test. The reviewer context must be independent from production and must not receive generator correctness claims, unnecessary deterministic pass conclusions, adversarial findings, or prior meaning-review conclusions. For every applicable meaning requirement preserve exact product location, required meaning, observed meaning, evidence-based comparison, applicable source evidence, and proposed SATISFIED/VIOLATED/UNDETERMINED determination. A hash cannot establish semantic meaning. Bare conclusions are insufficient. The application derives reviewer-independence consequence, evidence-sufficiency consequence, normalized counts, and final gate status.",
24:"Perform complete adversarial verification against the exact current finished product using only authorized requirements, tests, historical regressions/failure patterns, and attack context. The reviewer must be independent from production and must not receive generator reasoning/self-evaluation, prior reviewer conclusions, or conclusions telling the reviewer what to find. Deliberately execute every applicable attack category and active historical regression pattern, including missing/prohibited material, contradictions, impossible logic, unsupported facts, authority misrepresentation, wrong/stale versions, broken references, hidden assumptions/content, partial completion, nonsensical meaning, terminology inconsistency, unhandled exceptions, malformed/corrupt files, export/package corruption, superficial keyword compliance, and project-derived failure modes. Preserve attack, method, expected behavior, actual observation, evidence, severity, regression linkage, and defect/blocker linkage. The application derives independence, counts, and return-to-root-cause decision.",
25:"Inspect the exact final representation and delivery package completely. Use the current product, approved baseline identity, delivery artifacts, transformations, and required representations. Open or test every required delivery artifact and packaged file and inspect every required page, view, representation, and transformation. Preserve irreducible observations about clipping, omissions, blank content, broken layout, graphics, font substitution, overlap, hidden content, ordering, export corruption, package integrity, and project-specific human-interpreted meaning. Objective filenames, versions, byte sizes, hashes, artifact identities, transformation identities, and counts remain application-derived from verified bytes. No mandatory representation unknown may remain unresolved at completion.",
26:"Reconcile the complete current process evidence and product evidence before release. Use current baseline/product identity, deterministic results, meaning results, adversarial results, representation inspections, regressions, defects, blockers, evidence sufficiency, contradictions, instruction/requirement traceability, and current process/product audits. Perform substantive process and product review, identify every discrepancy, contradiction, missing evidence link, or unsupported conclusion, and explain whether both bodies of evidence consistently support progression. Do not hide contradictions or uncertainty inside aggregate counts. Semantic review content may be agent-authored, but current identities, missing-link detection, contradiction effects, evidence-sufficiency consequences, canonical counts, and release progression remain application-derived.",
27:"Perform advisory release-evidence review only; do not decide release. Inspect the complete current reconciled evidence for mandatory requirements, tests/results, regressions, process/product audits, representation inspection, defects, blockers, contradictions, baseline/product identity, and evidence freshness/sufficiency. Report observed blockers, violations, missing/undetermined evidence, and applicable rule analysis with evidence. The application alone creates the idempotent ACCEPTED, REJECTED, or BLOCKED release record and owns every release count, selected state, controlling decision rule, and normalized reason. Never override an application-derived contradiction, mandatory violation, blocker, or unknown.",
28:"Verify immediate pre-delivery artifact identity using the exact accepted Stage 27 release and the human-selected delivery artifacts. The application performs the authoritative one-to-one byte comparison by canonical ARTIFACT_ID plus authorized delivery filename, verified byte size, and SHA-256, independent of array order. Humans select or authorize delivery artifacts; agents do not calculate authoritative hashes or set delivery authorization. Inspect substantive discrepancies only. Missing, extra, duplicate, multiply matched, unauthorized rename, stale audit, post-review modification, changed byte size, or hash mismatch must prevent authorization.",
29:"Preserve and investigate the complete current evidence chain for every mandatory requirement. The application constructs the evidence graph from authority/human authority → requirement → instruction trace → execution or product element → every applicable test → every required current result → sufficient canonical evidence → current release → every applicable released artifact identity. Use investigation only to locate genuinely missing evidence or explain unresolved links. Do not fabricate links and do not treat raw-response identity as evidence identity. Structural completeness alone is insufficient: every evidence item must be current, correctly related, and capable of establishing its proposition, with current artifact identity where applicable. The application derives chain counts, completeness, coverage, missing/unknown requirement identities, and final evidence-chain determination.",
30:"Preserve permanent defect and regression history without rewriting it. Review the append-only defect registry, regression registry, future-baseline regression execution history, lifecycle/retirement state, and integrity evidence. Every confirmed defect must retain a permanent regression definition and actual execution history. Corrections are new superseding records, never edits to historical failure truth. Active regressions may be retired only through legitimate retirement authority while history remains preserved. Before a baseline can remain valid, the latest applicable execution of every active regression must have succeeded. The application owns registry identities, counts, lifecycle calculations, and integrity status."
}
full='const stageSpecial=Object.freeze({'+','.join(f"{k}:{v!r}" for k,v in stages.items())+'});\n'
t=t[:start]+full+t[end:]
old="const procedures=Object.freeze(Object.fromEntries(core.STAGES.map(stage=>[stage.number,stageSpecial[stage.number]||`Perform only Stage ${String(stage.number).padStart(2,'0')} — ${stage.title}. ${stage.result} Preserve only evidence and proposals permitted by the current stage contract; do not claim application-owned identity, counts, gates, hashes, scope, release, or byte facts.`])));"
if old not in t: raise SystemExit('generic procedure fallback declaration not found')
ops="""const operationSpecial=Object.freeze({17:Object.freeze({FREEZE:'For this FREEZE operation, inspect the corrected controlled versions/change set supplied by the application and report only substantive freeze observations needed to form the new candidate. Do not execute a run yet.',EXECUTE_RUN:'For this EXECUTE_RUN operation, execute only the reserved current RUN_ID and CONTEXT_ID against the exact corrected frozen candidate. Do not use any other run output or reviewer result.',VERIFY:'For this VERIFY operation, execute only the application-listed currently missing corrected-iteration verification triples using each stored execution route and evidence requirement.',COMPARE:'For this COMPARE operation, compare the complete current corrected-iteration ten-run verification set and preserve every material agreement, disagreement, violation, unknown, and variance.',ROOT_CAUSE:'For this ROOT_CAUSE operation, root-cause every current material corrected-iteration defect to the earliest responsible layer with evidence.',REGRESSION:'For this REGRESSION operation, create and actually execute the required regression definitions and fixtures for confirmed corrected-iteration defects under the current allowed phase.',CORRECT:'For this CORRECT operation, propose only evidence-supported responsible-layer corrections for the current confirmed RCA records; do not execute unrelated reruns in this operation.'}),19:Object.freeze({CONFIRM_FREEZE:'For this semantic freeze-confirmation operation, inspect the exact converged candidate versions and hashes supplied by the application and report any substantive reason they are not unchanged. Do not create a new candidate or execute runs here.',EXECUTE_RUN:'For this EXECUTE_RUN operation, execute only the reserved current confirmation RUN_ID and CONTEXT_ID using the exact unchanged package and no prior-run outputs.',VERIFY:'For this VERIFY operation, execute only the application-listed missing confirmation verification triples using the complete current suite and independent/evidence rules.',COMPARE:'For this COMPARE operation, compare all ten current confirmation runs and preserve every new disagreement, violation, unknown, defect, or correctness-affecting variance.',REGRESSION_VERIFY:'For this REGRESSION_VERIFY operation, execute every application-listed active applicable regression against the unchanged candidate and preserve actual results and sufficient evidence.',CONFIRM:'For this CONFIRM operation, report substantive confirmation observations only after all required execution, verification, comparison, and regression work is present. The application derives the final confirmation result.'})});
const procedures=Object.freeze(Object.fromEntries(core.STAGES.map(stage=>[stage.number,stageSpecial[stage.number]])));
function procedureFor(stage,operation){const base=procedures[stage];if(!base)throw new Error(`No explicit prompt procedure exists for Stage ${stage}.`);const extra=operationSpecial?.[stage]?.[operation];return extra?`${base} CURRENT OPERATION SUBCONTRACT: ${extra}`:base;}
"""
t=t.replace(old,ops,1)
# Use operation-complete procedure in the actual prompt body.
if '${procedures[stage]}' not in t: raise SystemExit('procedure interpolation not found')
t=t.replace('${procedures[stage]}','${procedureFor(stage,operation)}',1)
# Add explicit safe prior-stage stage-data projections in addition to record-level read contracts.
anchor="function contextFor(stage,state,operation,scope={}){const parts=[];"
if anchor not in t: raise SystemExit('contextFor anchor not found')
deps={2:[1],3:[1,2],4:[1,3],5:[4],6:[4,5],7:[4,6],8:[4,5,6,7],9:[8],10:[8,9],11:[10],12:[],13:[12],14:[12,13],15:[14],16:[14,15],17:[16],18:[17],19:[18],20:[19],21:[20],22:[21],23:[],24:[],25:[20,21],26:[20,21,22,23,24,25],27:[26],28:[27],29:[27,28],30:[15,20,29]}
depjs='const priorStageDependencies=Object.freeze('+repr(deps).replace("'",'"')+');\nfunction priorStageSnapshotBlock(stage,state){const ids=priorStageDependencies[stage]||[];if(!ids.length)return null;return ids.map(n=>{const s=state?.stages?.[n-1]||{};return `STAGE ${String(n).padStart(2,\'0\')} CURRENT ACCEPTED SNAPSHOT\\n${show({agentData:s.agentData||s.acceptedData||{},humanData:s.humanData||{},derivedData:s.derivedData||{}})}`;}).join(\'\\n\\n\');}\n'
t=t.replace(anchor,depjs+anchor+"const priorSnapshots=priorStageSnapshotBlock(stage,state);if(priorSnapshots)parts.push(`REQUIRED PRIOR-STAGE PROJECT DATA — APPLICATION SELECTED\\n${priorSnapshots}`);",1)
# Remove the old generic immediate-prior snapshot because explicit dependency projections now control this.
oldprior="if(stage>1&&![11,12,23,24].includes(stage)){const prior=state?.stages?.[stage-1]?{agentData:state.stages[stage-1].agentData||state.stages[stage-1].acceptedData||{},humanData:state.stages[stage-1].humanData||{},derivedData:state.stages[stage-1].derivedData||{}}:'NONE';parts.push(`PRIOR STAGE DECISION AND ACCEPTED DATA\\n${show(prior)}`);}"
if oldprior not in t: raise SystemExit('old immediate-prior context block not found')
t=t.replace(oldprior,'',1)
# Export procedureFor so the permanent all-stage audit can compare exact generated procedures.
export_anchor='globalThis.closedLoopPromptEngine=Object.freeze({'
if export_anchor not in t: raise SystemExit('prompt export anchor not found')
if 'procedureFor,' not in t[t.index(export_anchor):]:
    t=t.replace(export_anchor,export_anchor+'procedureFor,',1)
p.write_text(t)
